const $ = s => document.querySelector(s);
const categories = {sale:['Dine-in','Takeaway','Delivery','Other income'],expense:['Ingredients','Payroll','Rent & utilities','Supplies','Other expenses']};
const colors=['#668760','#a7b994','#e4c6a0','#d9dfcb','#b3c3bb'];
const localDate = d => `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const today=localDate(new Date());
const sample=()=>{
 const out=[];const current=new Date();const days=current.getDate();
 for(let i=1;i<=days;i++){
  const date=localDate(new Date(current.getFullYear(),current.getMonth(),i));
  out.push({id:crypto.randomUUID(),date,type:'sale',description:i===days?'Dinner service sales':'Daily restaurant sales',amount:Math.round(380+Math.sin(i*2)*160+i*13),category:i%3===0?'Delivery':'Dine-in',payment:i%2?'Card':'Cash'});
  if(i%2===1)out.push({id:crypto.randomUUID(),date,type:'expense',description:i===days?'Fresh produce & ingredients':'Market & kitchen supplies',amount:Math.round(95+Math.abs(Math.sin(i))*115),category:'Ingredients',payment:'Cash'});
 }
 out.push({id:crypto.randomUUID(),date:localDate(new Date(current.getFullYear(),current.getMonth(),1)),type:'expense',description:'Monthly restaurant rent',amount:1500,category:'Rent & utilities',payment:'Bank transfer'});
 out.push({id:crypto.randomUUID(),date:localDate(new Date(current.getFullYear(),current.getMonth(),Math.min(15,days))),type:'expense',description:'Team payroll',amount:2050,category:'Payroll',payment:'Bank transfer'});
 return out;
};
let state;try{state=JSON.parse(localStorage.getItem('bokrah-v1'))}catch{}
if(!state||!Array.isArray(state.entries))state={name:'Bokrah Restaurant',currency:'JOD',demo:true,entries:sample()};
let page='overview',period='month';
const escapeHTML=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const number=n=>new Intl.NumberFormat('en',{minimumFractionDigits:2,maximumFractionDigits:state.currency==='JOD'?3:2}).format(n);
const money=n=>`${number(n)} ${escapeHTML(state.currency)}`;
function notify(message){$('#toast').textContent=message;$('#toast').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#toast').style.display='none',3500)}
function persist(){try{localStorage.setItem('bokrah-v1',JSON.stringify(state));return true}catch{notify('Storage is unavailable or full. Export your records before closing.');return false}}
function selectedEntries(){const now=new Date();let start=period==='month'?localDate(new Date(now.getFullYear(),now.getMonth(),1)):period==='week'?localDate(new Date(now.getFullYear(),now.getMonth(),now.getDate()-6)):'0000-00-00';return state.entries.filter(e=>e.date>=start&&e.date<=today)}
const sum=(rows,type)=>rows.filter(e=>e.type===type).reduce((a,e)=>a+e.amount,0);
function table(rows,removable=false){if(!rows.length)return '<div class="empty">No transactions yet. Add your first sale or expense to get started.</div>';return `<table><thead><tr><th>TRANSACTION</th><th>DATE</th><th>CATEGORY</th><th>PAYMENT</th><th>AMOUNT</th>${removable?'<th></th>':''}</tr></thead><tbody>${[...rows].sort((a,b)=>b.date.localeCompare(a.date)).map(e=>`<tr><td><div class="description-cell"><span class="txn-icon ${e.type}">${e.type==='sale'?'↗':'↙'}</span><strong>${escapeHTML(e.description)}</strong></div></td><td>${new Date(e.date+'T12:00:00').toLocaleDateString('en-GB',{day:'2-digit',month:'short'})}</td><td><span class="badge">${escapeHTML(e.category)}</span></td><td>${escapeHTML(e.payment)}</td><td class="amount ${e.type==='expense'?'negative':''}">${e.type==='sale'?'+':'−'} ${money(e.amount)}</td>${removable?`<td><button class="delete" data-delete="${escapeHTML(e.id)}" aria-label="Delete ${escapeHTML(e.description)}">×</button></td>`:''}</tr>`).join('')}</tbody></table>`}
function render(){
 const rows=selectedEntries(),sales=sum(rows,'sale'),expenses=sum(rows,'expense'),profit=sales-expenses,margin=sales?profit/sales*100:0;
 document.title=state.name+' — Bokrah accounting';$('.workspace strong').textContent=state.name;$('#demo-banner').hidden=!state.demo;$('#footer-year').textContent=new Date().getFullYear();
 $('#date-label').textContent=period==='month'?new Date().toLocaleDateString('en-GB',{month:'long',year:'numeric'}):period==='week'?'Last 7 days':'All recorded dates';
 const stats=[['Total sales',sales,'↗',`${rows.filter(e=>e.type==='sale').length} income transactions`],['Total expenses',expenses,'↙',`${rows.filter(e=>e.type==='expense').length} expense transactions`],['Operating surplus',profit,'▤','Sales minus recorded expenses'],['Surplus margin',margin,'◴','Share of sales after expenses']];
 $('#stats').innerHTML=stats.map((s,i)=>`<div class="stat"><div class="stat-top">${s[0]}<span class="stat-icon">${s[2]}</span></div><div class="stat-value">${i===3?margin.toFixed(1)+'<small>%</small>':number(s[1])+`<small>${escapeHTML(state.currency)}</small>`}</div><div class="stat-bottom">${i===2?'<b>↗ Operating performance</b>':i===3?'<b>After recorded expenses</b>':escapeHTML(s[3])}</div></div>`).join('');
 renderRevenue(rows);renderExpenses(rows,expenses);
 $('#recent-table').innerHTML=table([...rows].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,5));
 renderLedger();
 $('#report-body').innerHTML=`<div class="report-line"><span>Total sales</span><strong>${money(sales)}</strong></div>`+categories.expense.map(c=>`<div class="report-line"><span>${c}</span><span>${money(rows.filter(e=>e.type==='expense'&&e.category===c).reduce((a,e)=>a+e.amount,0))}</span></div>`).join('')+`<div class="report-line"><span>Total expenses</span><strong>${money(expenses)}</strong></div><div class="report-line total"><span>Operating surplus</span><span>${money(profit)}</span></div><div class="report-line"><span>Surplus margin</span><strong>${margin.toFixed(1)}%</strong></div>`;
}
function renderRevenue(rows){
 const now=new Date();let start,end=now;
 if(period==='month')start=new Date(now.getFullYear(),now.getMonth(),1);
 else if(period==='week')start=new Date(now.getFullYear(),now.getMonth(),now.getDate()-6);
 else start=rows.length?new Date([...rows].sort((a,b)=>a.date.localeCompare(b.date))[0].date+'T00:00:00'):new Date(now.getFullYear(),now.getMonth(),1);
 const count=7,days=Math.max(1,Math.floor((end-start)/86400000)+1),buckets=Array.from({length:count},()=>({sale:0,expense:0}));
 rows.forEach(e=>{const idx=Math.min(count-1,Math.max(0,Math.floor(((new Date(e.date+'T00:00:00')-start)/86400000)/days*count)));buckets[idx][e.type]+=e.amount});
 const max=Math.max(100,...buckets.flatMap(b=>[b.sale,b.expense]));const top=Math.ceil(max/100)*100;
 $('#revenue-chart').innerHTML=`<div class="chart"><div class="axis">${[1,.75,.5,.25,0].map(n=>`<span>${n*top>=1000?(n*top/1000).toFixed(1)+'k':Math.round(n*top)}</span>`).join('')}</div><div class="plot">${buckets.map((b,i)=>{const d=new Date(start);d.setDate(d.getDate()+Math.floor(days/count*i));return `<div class="bar-group"><div class="bar" style="height:${b.sale/top*100}%" title="Sales: ${money(b.sale)}"></div><div class="bar expense" style="height:${b.expense/top*100}%" title="Expenses: ${money(b.expense)}"></div><span class="bar-label">${d.toLocaleDateString('en-GB',{day:'numeric',month:'short'})}</span></div>`}).join('')}</div></div>`;
}
function renderExpenses(rows,total){const groups=categories.expense.map((c,i)=>({name:c,color:colors[i],value:rows.filter(e=>e.type==='expense'&&e.category===c).reduce((a,e)=>a+e.amount,0)})).filter(c=>c.value>0);let cursor=0;const gradient=groups.map(g=>{const start=cursor;cursor+=g.value/total*100;return `${g.color} ${start}% ${cursor}%`}).join(',');$('#expense-chart').innerHTML=`<div class="donut-row"><div class="donut" style="background:${total?`conic-gradient(${gradient})`:'#edf1e8'}"><div class="donut-center"><span>Total expenses · ${escapeHTML(state.currency)}</span><strong>${new Intl.NumberFormat('en',{maximumFractionDigits:0}).format(total)}</strong></div></div></div><div class="category-list">${groups.length?groups.map(g=>`<div class="category-row"><span><i style="background:${g.color}"></i>${g.name}</span><b>${(g.value/total*100).toFixed(0)}%</b></div>`).join(''):'<p>No recorded expenses yet.</p>'}</div>`}
function renderLedger(){const q=$('#search').value.toLowerCase();$('#ledger-table').innerHTML=table(selectedEntries().filter(e=>(page==='sales'?e.type==='sale':page==='expenses'?e.type==='expense':true)&&[e.description,e.category,e.payment].some(v=>v.toLowerCase().includes(q))),true)}
function navigate(next){page=next;document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const titles={overview:['Business overview','Good food. Healthy numbers. See how Bokrah is doing.'],sales:['Sales','Every service, every sale. Keep track of your income.'],expenses:['Expenses','Know what goes into keeping your restaurant running.'],reports:['Financial reports','A clear view of your restaurant’s recorded performance.'],settings:['Workspace settings','A little setup for a smoother day.'],transactions:['All transactions','All your restaurant activity in one place.']};$('#page-title').textContent=titles[page][0];$('#page-subtitle').textContent=titles[page][1];$('#breadcrumb').innerHTML=`Workspace <span class="slash">/</span> <b>${titles[page][0]}</b>`;$('#overview').hidden=page!=='overview';$('#ledger').hidden=!['sales','expenses','transactions'].includes(page);$('#reports').hidden=page!=='reports';$('#settings').hidden=page!=='settings';$('.toolbar').hidden=page==='settings';$('#ledger-title').textContent=page==='sales'?'Sales transactions':page==='expenses'?'Expense transactions':'All transactions';$('#new-entry').hidden=page==='settings';const f=$('#settings-form');f.elements.name.value=state.name;f.elements.currency.value=state.currency;renderLedger();window.scrollTo(0,0)}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>navigate(b.dataset.page));
document.querySelectorAll('[data-period]').forEach(b=>b.onclick=()=>{period=b.dataset.period;document.querySelectorAll('[data-period]').forEach(t=>t.classList.toggle('selected',t===b));render()});
$('#view-all').onclick=()=>navigate('transactions');$('#search').oninput=renderLedger;
const form=$('#entry-form');function updateCategories(){form.elements.category.innerHTML=categories[form.elements.type.value].map(c=>`<option>${c}</option>`).join('')}
form.elements.type.onchange=updateCategories;
$('#new-entry').onclick=()=>{form.reset();form.elements.type.value=page==='expenses'?'expense':'sale';form.elements.date.value=today;form.elements.date.max=today;updateCategories();$('#entry-dialog').showModal()};
document.querySelectorAll('.close').forEach(b=>b.onclick=()=>$('#entry-dialog').close());
form.onsubmit=e=>{e.preventDefault();const data=new FormData(form),amount=Number(data.get('amount'));if(!Number.isFinite(amount)||amount<=0||amount>999999999||data.get('date')>today||!data.get('description').trim()){notify('Enter a description, valid amount, and date.');return}const row={id:crypto.randomUUID(),type:data.get('type'),description:data.get('description').trim(),amount,date:data.get('date'),category:data.get('category'),payment:data.get('payment')};state.entries.push(row);if(!persist()){state.entries.pop();return}$('#entry-dialog').close();render();notify('Transaction saved')};
document.addEventListener('click',e=>{const b=e.target.closest('[data-delete]');if(!b)return;if(confirm('Delete this transaction?')){const prior=state.entries;state.entries=state.entries.filter(t=>t.id!==b.dataset.delete);if(!persist()){state.entries=prior;return}render();notify('Transaction deleted')}});
$('#start-fresh').onclick=()=>{if(!confirm('Remove all sample data and start with an empty ledger? Export first if you have added records you want to keep.'))return;const prior=state;state={...state,demo:false,entries:[]};if(!persist()){state=prior;return}render();notify('Your ledger is ready for your first transaction')};
$('#settings-form').onsubmit=e=>{e.preventDefault();const prior={...state};state.name=e.target.elements.name.value.trim();state.currency=e.target.elements.currency.value;if(!state.name)return;if(!persist()){state=prior;return}render();notify('Workspace settings saved')};
$('#export').onclick=()=>{const rows=selectedEntries().filter(e=>page==='sales'?e.type==='sale':page==='expenses'?e.type==='expense':true);const cell=v=>'"'+String(v).replace(/^[=+@\-\t\r]/,"'$&").replace(/"/g,'""')+'"';const csv=[['Date','Type','Description','Category','Payment','Amount','Currency'],...rows.map(e=>[e.date,e.type,e.description,e.category,e.payment,e.amount,state.currency])].map(r=>r.map(cell).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob(['\uFEFF'+csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=`bokrah-${page}-${today}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('CSV exported')};
$('#print').onclick=()=>window.print();render();persist();
